28	export interface ScaleRawExtentResult {
29	    // `min`/`max` defines data available range, determined by
30	    // `dataMin`/`dataMax` and explicit specified min max related option.
31	    // The final extent will be based on the `min`/`max` and may be enlarge
32	    // a little (say, "nice strategy", e.g., niceScale, boundaryGap).
33	    // Ensure `min`/`max` be finite number or NaN here.
34	    // (not to be null/undefined) `NaN` means min/max axis is blank.
35	    readonly min: number;
36	    readonly max: number;
37	    // `minFixed`/`maxFixed` marks that `min`/`max` should be used
38	    // in the final extent without other "nice strategy".
39	    readonly minFixed: boolean;
40	    readonly maxFixed: boolean;
41	    // Mark that the axis should be blank.
42	    readonly isBlank: boolean;
