82	    /**
83	     * Parameters depending on outside (like model, user callback)
84	     * are prepared and fixed here.
85	     */
86	    private _prepareParams(
87	        scale: Scale,
88	        model: AxisBaseModel,
89	        // Usually: data extent from all series on this axis.
90	        dataExtent: number[]
91	    ) {
92	        if (dataExtent[1] < dataExtent[0]) {
93	            dataExtent = [NaN, NaN];
94	        }
95	        this._dataMin = dataExtent[0];
96	        this._dataMax = dataExtent[1];
97	
98	        const isOrdinal = this._isOrdinal = scale.type === 'ordinal';
99	        this._needCrossZero = scale.type === 'interval' && model.getNeedCrossZero && model.getNeedCrossZero();
100	
101	        let axisMinValue = model.get('min', true);
102	        if (axisMinValue == null) {
103	            axisMinValue = model.get('startValue', true);
104	        }
105	        const modelMinRaw = this._modelMinRaw = axisMinValue;
106	        if (isFunction(modelMinRaw)) {
107	            // This callback always provides users the full data extent (before data is filtered).
108	            this._modelMinNum = parseAxisModelMinMax(scale, modelMinRaw({
109	                min: dataExtent[0],
110	                max: dataExtent[1]
111	            }));
112	        }
113	        else if (modelMinRaw !== 'dataMin') {
114	            this._modelMinNum = parseAxisModelMinMax(scale, modelMinRaw);
115	        }
116	
117	        const modelMaxRaw = this._modelMaxRaw = model.get('max', true);
118	        if (isFunction(modelMaxRaw)) {
119	            // This callback always provides users the full data extent (before data is filtered).
120	            this._modelMaxNum = parseAxisModelMinMax(scale, modelMaxRaw({
121	                min: dataExtent[0],
122	                max: dataExtent[1]
123	            }));
124	        }
125	        else if (modelMaxRaw !== 'dataMax') {
126	            this._modelMaxNum = parseAxisModelMinMax(scale, modelMaxRaw);
127	        }
128	
129	        if (isOrdinal) {
130	            // FIXME: there is a flaw here: if there is no "block" data processor like `dataZoom`,
131	            // and progressive rendering is using, here the category result might just only contain
132	            // the processed chunk rather than the entire result.
133	            this._axisDataLen = model.getCategories().length;
134	        }
135	        else {
136	            const boundaryGap = (model as AxisBaseModel<CategoryAxisBaseOption>).get('boundaryGap');
137	            const boundaryGapArr = isArray(boundaryGap)
138	                ? boundaryGap : [boundaryGap || 0, boundaryGap || 0];
139	
140	            if (typeof boundaryGapArr[0] === 'boolean' || typeof boundaryGapArr[1] === 'boolean') {
141	                if (__DEV__) {
142	                    console.warn('Boolean type for boundaryGap is only '
143	                        + 'allowed for ordinal axis. Please use string in '
144	                        + 'percentage instead, e.g., "20%". Currently, '
145	                        + 'boundaryGap is set to be 0.');
146	                }
147	                this._boundaryGapInner = [0, 0];
148	            }
149	            else {
150	                this._boundaryGapInner = [
151	                    parsePercent(boundaryGapArr[0], 1),
152	                    parsePercent(boundaryGapArr[1], 1)
153	                ];
154	            }
155	        }
156	    }
