158	    /**
159	     * Calculate extent by prepared parameters.
160	     * This method has no external dependency and can be called duplicatedly,
161	     * getting the same result.
162	     * If parameters changed, should call this method to recalcuate.
163	     */
164	    calculate(): ScaleRawExtentResult {
165	        // Notice: When min/max is not set (that is, when there are null/undefined,
166	        // which is the most common case), these cases should be ensured:
167	        // (1) For 'ordinal', show all axis.data.
168	        // (2) For others:
169	        //      + `boundaryGap` is applied (if min/max set, boundaryGap is
170	        //      disabled).
171	        //      + If `needCrossZero`, min/max should be zero, otherwise, min/max should
172	        //      be the result that originalExtent enlarged by boundaryGap.
173	        // (3) If no data, it should be ensured that `scale.setBlank` is set.
174	
175	        const isOrdinal = this._isOrdinal;
176	        const dataMin = this._dataMin;
177	        const dataMax = this._dataMax;
178	        const axisDataLen = this._axisDataLen;
179	        const boundaryGapInner = this._boundaryGapInner;
180	
181	        const span = !isOrdinal
182	            ? ((dataMax - dataMin) || Math.abs(dataMin))
183	            : null;
184	
185	        // Currently if a `'value'` axis model min is specified as 'dataMin'/'dataMax',
186	        // `boundaryGap` will not be used. It's the different from specifying as `null`/`undefined`.
187	        let min = this._modelMinRaw === 'dataMin' ? dataMin : this._modelMinNum;
188	        let max = this._modelMaxRaw === 'dataMax' ? dataMax : this._modelMaxNum;
189	
190	        // If `_modelMinNum`/`_modelMaxNum` is `null`/`undefined`, should not be fixed.
191	        let minFixed = min != null;
192	        let maxFixed = max != null;
193	
194	        if (min == null) {
195	            min = isOrdinal
196	                ? (axisDataLen ? 0 : NaN)
197	                : dataMin - boundaryGapInner[0] * span;
198	        }
199	        if (max == null) {
200	            max = isOrdinal
201	                ? (axisDataLen ? axisDataLen - 1 : NaN)
202	                : dataMax + boundaryGapInner[1] * span;
203	        }
204	
205	        (min == null || !isFinite(min)) && (min = NaN);
206	        (max == null || !isFinite(max)) && (max = NaN);
207	
208	        const isBlank = eqNaN(min)
209	            || eqNaN(max)
210	            || (isOrdinal && !axisDataLen);
211	
212	        // If data extent modified, need to recalculated to ensure cross zero.
213	        if (this._needCrossZero) {
214	            // Axis is over zero and min is not set
215	            if (min > 0 && max > 0 && !minFixed) {
216	                min = 0;
217	                // minFixed = true;
218	            }
219	            // Axis is under zero and max is not set
220	            if (min < 0 && max < 0 && !maxFixed) {
221	                max = 0;
222	                // maxFixed = true;
223	            }
224	            // PENDING:
225	            // When `needCrossZero` and all data is positive/negative, should it be ensured
226	            // that the results processed by boundaryGap are positive/negative?
227	            // If so, here `minFixed`/`maxFixed` need to be set.
228	        }
229	
230	        const determinedMin = this._determinedMin;
231	        const determinedMax = this._determinedMax;
232	        if (determinedMin != null) {
233	            min = determinedMin;
234	            minFixed = true;
235	        }
236	        if (determinedMax != null) {
237	            max = determinedMax;
238	            maxFixed = true;
239	        }
240	
241	        // Ensure min/max be finite number or NaN here. (not to be null/undefined)
242	        // `NaN` means min/max axis is blank.
243	        return {
244	            min: min,
245	            max: max,
246	            minFixed: minFixed,
247	            maxFixed: maxFixed,
248	            isBlank: isBlank
249	        };
250	    }
