280	/**
281	 * Get scale min max and related info only depends on model settings.
282	 * This method can be called after coordinate system created.
283	 * For example, in data processing stage.
284	 *
285	 * Scale extent info probably be required multiple times during a workflow.
286	 * For example:
287	 * (1) `dataZoom` depends it to get the axis extent in "100%" state.
288	 * (2) `processor/extentCalculator` depends it to make sure whether axis extent is specified.
289	 * (3) `coordSys.update` use it to finally decide the scale extent.
290	 * But the callback of `min`/`max` should not be called multiple times.
291	 * The code below should not be implemented repeatedly either.
292	 * So we cache the result in the scale instance, which will be recreated at the beginning
293	 * of the workflow (because `scale` instance will be recreated each round of the workflow).
294	 */
295	export function ensureScaleRawExtentInfo(
296	    scale: Scale,
297	    model: AxisBaseModel,
298	    // Usually: data extent from all series on this axis.
299	    originalExtent: number[]
300	): ScaleRawExtentInfo {
301	
302	    // Do not permit to recreate.
303	    let rawExtentInfo = scale.rawExtentInfo;
304	    if (rawExtentInfo) {
305	        return rawExtentInfo;
306	    }
307	
308	    rawExtentInfo = new ScaleRawExtentInfo(scale, model, originalExtent);
309	    // @ts-ignore
310	    scale.rawExtentInfo = rawExtentInfo;
311	
312	    return rawExtentInfo;
313	}
